# ঘোষিত Requirements Checklist (কোনো মাপা Model Benchmark নয়—স্বচ্ছ সিদ্ধান্ত কাঠামো!)
def recommend_stack(req):
    layers = ["1) Prompting + Few-shot Baseline (measure on held-out eval first!)"]
    if req["fresh_sources"]:
        if req["offline"]:
            layers.append("2) Versioned Local RAG (offline index + verifiable citations)")
        else:
            layers.append("2) Versioned RAG (retrieval + citation grounding)")
    if req["strict_style_or_schema"] and not req["prompting_met_target"]:
        if req["limited_vram"]:
            layers.append("3) SFT via LoRA/QLoRA (PEFT) — ablate gain over Prompting!")
        else:
            layers.append("3) SFT via LoRA or Full FT — ablate gain + retention!")
    if req["subtle_human_preference"]:
        layers.append("4) Preference Alignment (DPO) + separate Factuality/Safety eval")
    return layers

# আমাদের মূল চুক্তি উদাহরণ (fresh_sources + stable_style + offline)
base_req = {
    "name": "Offline Clinical/Doc Assistant",
    "fresh_sources": True,
    "strict_style_or_schema": True,
    "prompting_met_target": False,
    "offline": True,
    "limited_vram": True,
    "subtle_human_preference": False,
}
assert base_req["fresh_sources"] and base_req["offline"]

scenarios = [
    base_req,
    {
        "name": "Daily Flight Refund Bot",
        "fresh_sources": True,
        "strict_style_or_schema": False,
        "prompting_met_target": True,
        "offline": False,
        "limited_vram": True,
        "subtle_human_preference": False,
    },
    {
        "name": "Simple 3-Bullet Summarizer (Prompting Already 94%)",
        "fresh_sources": False,
        "strict_style_or_schema": True,
        "prompting_met_target": True,
        "offline": False,
        "limited_vram": True,
        "subtle_human_preference": False,
    },
    {
        "name": "Polite Customer Refusal Coach",
        "fresh_sources": False,
        "strict_style_or_schema": True,
        "prompting_met_target": False,
        "offline": False,
        "limited_vram": True,
        "subtle_human_preference": True,
    },
]

for sc in scenarios:
    stack = recommend_stack(sc)
    print(f"=== {sc['name']} ===")
    for step in stack:
        print("  ", step)
